{"policy":"permit (
    principal is Picker,
    action == Action::"pickOrder",
    resource is Order
);

permit (
    principal is ForkliftOperator,
    action == Action::"pickOrder",
    resource is Order
)
when {
    resource.requestedBy == principal.user &&
    resource.crossesBulkPickThreshold
};

forbid (
    principal,
    action == Action::"pickOrder",
    resource is Order
)
when {
    (principal is Picker || principal is ForkliftOperator) &&
    !context.hasBadgedInOnSiteForShift
};

forbid (
    principal,
    action == Action::"pickOrder",
    resource is Order
)
when {
    !resource.crossesBulkPickThreshold &&
    ((principal is Picker && resource.requestedBy == principal.user) ||
     (principal is ForkliftOperator && resource.requestedBy == principal.user))
};"}
